  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Ofloxacin, a high-transfer fluoroquinolone analogue, had absolute oral bioavailability >95% in healthy volunteers after a 200 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Trovafloxacin, a high-transfer fluoroquinolone analogue, had absolute oral bioavailability of 88% after a 200 mg single oral dose in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Zalcitabine, a high-transfer nucleoside analogue, showed approximately 70-90% oral bioavailability in patients with AIDS/ARC.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Zidovudine, a high-transfer nucleoside analogue, had absolute oral bioavailability of 64% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C75"],
      "claim": "Cladribine, a high-transfer nucleoside analogue, showed oral bioavailability of 38% (25-67%) in patients, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Didanosine, a high-transfer nucleoside analogue, had absolute oral bioavailability of 30-54% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Emtricitabine, a high-transfer nucleoside analogue, had oral bioavailability of 92% in healthy adult volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Sildenafil, a high-transfer heteroaromatic analogue, had mean absolute oral bioavailability of 41% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Nebivolol, a high-transfer fluorinated analogue, had absolute oral bioavailability of 96% in extensive metabolizers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report oral bioavailability values above the 20% threshold, mostly 38-100%, with no consistent evidence of F<20%. The query's moderate MW/lipophilicity and high TPSA/HBA are uncertain physicochemical priors but are outweighed by the consistent experimental pattern. Therefore predict high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "No specific metabolism, transporter, or solubility data for the query.",
    "Some analogue values are population- or formulation-specific, e.g., pediatric didanosine.",
    "High TPSA and HBA count leave residual permeability uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

